/* 舞台スケッチγ：セリフ編集画面（2026-09-24 本人指示）。
 * 「照明デザイン」の横の「セリフ」タブで、画面1枚を使って台本を編集する。
 *   ・セリフの文字・話者の編集、行の並べ替え・追加・削除、セリフキューへの割り当て
 *   ・U-10（2026-09-24）: 行をダブルクリックすると、その場でセリフの文字を直せる（右の「選んだセリフ」も残す）
 * 本人決定: 台本は新しい台本データ（project.script）に持つ／1キュー＝1行／話者は演者から選ぶ＋自由入力も可。
 * 保存形式: project.script = { version: 1, lines: [{ id, sceneId, castId, speaker, text, cueId }] }
 *   ・行の並び＝配列の順。画面ではシーンの順に分けて出す（同じシーンの中は配列の順）。
 *   ・キューとの結び付きは行の側（cueId）に持つ（キューの未知の項目は読み込み時に落ちるため）。
 *   ・シーンメモの【台本】は「取り込む」で一度だけ写す。メモ自体は消さない。
 * 本体への書き込みは SHOSAI_STAGE_SESSION_BRIDGE.applyScriptEdit だけ（取り消し1回で戻る単位）。
 * キューの番号・時刻は、タイムラインが出す「stage-timeline-vox-cues」から読む（セリフキューパネルと同じ）。 */
(function initGammaRuntimestage_script_editor() {
  "use strict";
  if (!window.SHOSAI_STAGE_SESSION_BRIDGE) {
    window.addEventListener("stage-gamma-runtime-ready", initGammaRuntimestage_script_editor, {once:true});
    return;
  }

  const bridge = window.SHOSAI_STAGE_SESSION_BRIDGE;
  const host = document.getElementById("gamma-script-workspace");
  if (!bridge || !host || typeof bridge.applyScriptEdit !== "function") return;

  const panelApi = () => window.SHOSAI_VOX_PANEL;
  const tx = (japanese) => {
    const model = window.SHOSAI_STAGE_I18N_MODEL;
    return model && typeof model.text === "function"
      ? model.text(document.documentElement.lang || "ja", japanese) : japanese;
  };
  const el = (tag, className, text) => {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  };
  const rid = () => `line-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
  const OTHER_SPEAKER = "__other__";

  let project = null;          // 本体から写した最新のショー（読むだけ）
  let script = null;           // 編集中の台本（本体の project.script の写し）
  let voxCues = [];            // タイムラインのセリフキュー（id・表示名・シーン・秒）
  let selectedId = null;
  let query = "";
  let isOpen = false;
  let commitTimer = 0;
  let pendingText = null;      // 入力中の文字（まだ本体へ送っていない）
  let dragging = null;

  /* ---------- データ ---------- */

  function readProject() {
    try {
      const doc = JSON.parse(bridge.exportDocumentString());
      project = doc && doc.project ? doc.project : null;
    } catch (_) { project = null; }
    const saved = typeof bridge.getProjectScript === "function" ? bridge.getProjectScript() : null;
    script = saved && Array.isArray(saved.lines) ? saved : null;
  }

  const scenes = () => (project && Array.isArray(project.scenes) ? project.scenes : []);
  const sceneRows = () => scenes().filter((row) => row && row.kind === "scene");
  const cast = () => (project && Array.isArray(project.cast) ? project.cast : []);
  const castById = (id) => cast().find((member) => member.id === id) || null;

  // シーンの番号（本体のシーン一覧と同じ「1-6」の形）
  function sceneNumbers() {
    const counters = [];
    const numbers = new Map();
    scenes().forEach((row) => {
      const depth = Math.max(0, Math.floor(Number(row && row.depth) || 0));
      counters[depth] = (counters[depth] || 0) + 1;
      counters.length = depth + 1;
      if (row && row.id) numbers.set(row.id, counters.join("-"));
    });
    return numbers;
  }

  function speakerOf(line) {
    const member = line.castId ? castById(line.castId) : null;
    return { name: member ? member.name : (line.speaker || ""), color: member ? member.color : null };
  }

  const cueById = (id) => voxCues.find((cue) => cue.id === id) || null;
  const lineForCue = (cueId) => (script ? script.lines.find((line) => line.cueId === cueId) : null) || null;

  /* シーンメモの【台本】から取り込む。シーンの n 行目＝そのシーンの n 番目のセリフキュー（セリフキューパネルと同じ当て方）。
   * 話者が演者名と同じなら演者に結び付ける。 */
  function buildFromNotes() {
    const api = panelApi();
    if (!api) return { version: 1, lines: [] };
    const lines = [];
    sceneRows().forEach((scene) => {
      const found = api.scriptLinesFromNote(scene.note);
      const cues = voxCues.filter((cue) => cue.sceneId === scene.id).sort((a, b) => a.seconds - b.seconds);
      found.forEach((item, index) => {
        const member = cast().find((m) => m.name === item.speaker) || null;
        lines.push({
          id: rid(), sceneId: scene.id, castId: member ? member.id : null,
          speaker: member ? "" : item.speaker, text: item.line,
          cueId: cues[index] ? cues[index].id : null,
        });
      });
    });
    return { version: 1, importedAt: new Date().toISOString(), lines };
  }

  function countNoteLines() {
    const api = panelApi();
    if (!api) return 0;
    return sceneRows().reduce((sum, scene) => sum + api.scriptLinesFromNote(scene.note).length, 0);
  }

  /* 本体へ書き込む（取り消し1回の単位）。addCues / removeCueIds はキューの追加・削除を同じ単位にまとめる。 */
  let selfCommit = false;
  function commit(extra = {}) {
    if (!script) return null;
    flushTextTimer(false);
    selfCommit = true;
    const result = bridge.applyScriptEdit({ script, ...extra });
    selfCommit = false;
    /* 本体が整えた値（消えたキューの割り当てを外す等）を、手元の行へ書き戻す。
     * 行のオブジェクトは差し替えない（右の欄が同じ行を持ち続けて編集できるように）。 */
    if (result && result.script && Array.isArray(result.script.lines)) {
      const byId = new Map(result.script.lines.map((line) => [line.id, line]));
      script.lines.forEach((line) => { const fixed = byId.get(line.id); if (fixed) Object.assign(line, fixed); });
    }
    return result;
  }

  function flushTextTimer(send = true) {
    if (!commitTimer) return;
    clearTimeout(commitTimer);
    commitTimer = 0;
    if (send && pendingText) commit();
    pendingText = null;
  }

  /* ---------- 台本の書き出し（A4・印刷／PDF） ---------- */
  const escapeHtml = (value) => String(value === null || value === undefined ? "" : value).replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
  function scriptPrintDocument() {
    const numbers = new Map();
    const counters = [];
    scenes().forEach((row) => {
      const depth = Math.max(0, Math.floor(Number(row && row.depth) || 0));
      counters[depth] = (counters[depth] || 0) + 1; counters.length = depth + 1;
      if (row && row.id) numbers.set(row.id, counters.join("-"));
    });
    const cueName = new Map((voxCues || []).map((cue) => [cue.id, cue.displayName || ""]));
    const lines = script && Array.isArray(script.lines) ? script.lines : [];
    const linesByScene = new Map();
    lines.forEach((line) => { if (!linesByScene.has(line.sceneId)) linesByScene.set(line.sceneId, []); linesByScene.get(line.sceneId).push(line); });
    const speakerOf = (line) => { const member = castById(line.castId); return (member && member.name) || line.speaker || ""; };
    const body = scenes().map((row) => {
      if (!row) return "";
      const number = numbers.get(row.id) || "";
      if (row.kind === "section") return `<h2 class="script-print-section">${escapeHtml(number)} ${escapeHtml(row.title || "")}</h2>`;
      const items = linesByScene.get(row.id) || [];
      const rows = items.map((line) => `<div class="script-print-line"><div class="script-print-speaker">${escapeHtml(speakerOf(line))}</div><div class="script-print-text">${escapeHtml(line.text || "").replace(/\n/g, "<br>")}</div><div class="script-print-cue">${escapeHtml(cueName.get(line.cueId) || "")}</div></div>`).join("");
      return `<section class="script-print-scene"><h3>${escapeHtml(number)} ${escapeHtml(row.title || "")}</h3>${rows || `<p class="script-print-empty">${escapeHtml(tx("（セリフなし）"))}</p>`}</section>`;
    }).join("");
    const title = (project && project.title) || tx("台本");
    const stamp = window.STAGE_TIME_DOMAIN.dateText(new Date(), document.documentElement.lang || "ja");
    return `<!DOCTYPE html><html lang="${escapeHtml(document.documentElement.lang || "ja")}"><head><meta charset="utf-8"><title>${escapeHtml(title)} — ${escapeHtml(tx("台本"))}</title>
<style>
@page { size: A4 portrait; margin: 16mm 14mm; }
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; color: #1c1a17; background: #fff; font-family: 'Hiragino Mincho ProN', 'Hiragino Kaku Gothic ProN', serif; font-size: 11.5pt; line-height: 1.7; }
body { padding: 16mm 14mm; }
@media print { body { padding: 0; } }
.script-print-head { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1.5px solid #1c1a17; padding-bottom: 6px; margin-bottom: 14px; }
.script-print-head h1 { margin: 0; font-size: 16pt; }
.script-print-head p { margin: 0; font-size: 9.5pt; color: #555; }
.script-print-section { margin: 18px 0 6px; padding: 4px 8px; background: #eee; font-size: 12.5pt; break-after: avoid; }
.script-print-scene { margin: 0 0 10px; break-inside: avoid; }
.script-print-scene h3 { margin: 10px 0 4px; font-size: 11.5pt; border-left: 3px solid #b08a4a; padding-left: 8px; break-after: avoid; }
.script-print-line { display: grid; grid-template-columns: 7.2em 1fr 8em; gap: 0 10px; padding: 3px 0; border-bottom: 1px dotted #ccc; break-inside: avoid; }
.script-print-speaker { font-weight: 700; }
.script-print-cue { color: #777; font-size: 9pt; text-align: right; }
.script-print-empty { margin: 0; color: #888; font-size: 10pt; }
</style></head><body>
<header class="script-print-head"><h1>${escapeHtml(title)}</h1><p>${escapeHtml(tx("台本"))} · ${escapeHtml(stamp)}</p></header>
${body}
</body></html>`;
  }
  function exportScript() {
    readProject();
    if (!project) return;
    const url = URL.createObjectURL(new Blob([scriptPrintDocument()], { type: "text/html" }));
    const win = window.open(url, "_blank");
    if (!win) { window.GAMMA_SURFACE_DIALOG.notice(tx("台本を開けませんでした。ポップアップの許可を確認してください。")); URL.revokeObjectURL(url); return; }
  }

  /* ---------- 画面の骨組み ---------- */

  const ui = {};
  function build() {
    host.textContent = "";
    const root = el("div", "script-ed");
    const head = el("header", "script-ed-head");
    ui.summary = el("p", "script-ed-summary");
    const actions = el("div", "script-ed-actions");
    // 台本の書き出し（2026-09-24 本人指示）: 「シーンメモから取り込み直す」の左。A4縦の印刷用の窓を開き、印刷かPDF保存へ。
    ui.exportScript = el("button", "script-ed-btn quiet", tx("台本を書き出す"));
    ui.exportScript.type = "button";
    ui.exportScript.dataset.tipDescription = "台本をA4縦の印刷用画面で開きます。";
    ui.exportScript.title = tx("A4の印刷用の窓で開きます（印刷・PDF保存）");
    ui.exportScript.addEventListener("click", exportScript);
    ui.reimport = el("button", "script-ed-btn quiet", tx("シーンメモから取り込み直す"));
    ui.reimport.type = "button";
    ui.reimport.dataset.tipDescription = "現在の台本を、シーンメモの台本から作り直します。確認後に置き換えます。";
    ui.reimport.addEventListener("click", reimport);
    ui.addLine = el("button", "script-ed-btn primary", tx("＋ 行を足す"));
    ui.addLine.type = "button";
    ui.addLine.dataset.tipDescription = "台本に新しい行を追加します。行を選んでいるときは、その下に入ります。";
    ui.addLine.addEventListener("click", () => addLineAfter(selectedId));
    actions.append(ui.exportScript, ui.reimport, ui.addLine);
    head.append(ui.summary, actions);

    const body = el("div", "script-ed-body");
    // 左: シーンの目次
    const scenesBox = el("section", "script-ed-box script-ed-scenes");
    scenesBox.setAttribute("aria-label", tx("シーン"));
    scenesBox.append(el("h2", "script-ed-title", tx("シーン")));
    ui.search = el("input", "script-ed-search");
    ui.search.type = "search";
    ui.search.placeholder = tx("セリフ・話者で探す");
    ui.search.setAttribute("aria-label", tx("セリフ・話者で探す"));
    ui.search.addEventListener("input", () => { query = ui.search.value.trim(); renderLines(); });
    ui.toc = el("ol", "script-ed-toc");
    scenesBox.append(ui.search, ui.toc);
    // 中央: 台本
    const linesBox = el("section", "script-ed-box script-ed-script");
    linesBox.setAttribute("aria-label", tx("台本"));
    const linesHead = el("div", "script-ed-script-head");
    linesHead.append(el("h2", "script-ed-title", tx("台本")),
      el("p", "script-ed-hint", tx("行を押して選ぶ。ダブルクリックでその場で直す。⠿ を持って並べ替え（Alt＋↑↓でも動かせます）。")));
    ui.lines = el("div", "script-ed-lines");
    ui.lines.setAttribute("role", "listbox");
    ui.lines.setAttribute("aria-label", tx("台本の行"));
    ui.lines.tabIndex = 0;
    ui.lines.addEventListener("keydown", onListKey);
    linesBox.append(linesHead, ui.lines);
    // 右: 選んだセリフ
    ui.inspector = el("section", "script-ed-box script-ed-inspector");
    ui.inspector.setAttribute("aria-label", tx("選んだセリフ"));
    body.append(scenesBox, linesBox, ui.inspector);
    mountColumnHandles(body, scenesBox, ui.inspector);

    ui.empty = el("div", "script-ed-empty");
    root.append(head, body, ui.empty);
    host.append(root);
    ui.body = body;
    // 舞台側の矢印キー（キュー送り・シーン送り）へ渡さない
    host.addEventListener("keydown", (event) => {
      if (event.key.startsWith("Arrow")) event.stopPropagation();
    });
  }

  /* ---------- V-03（2026-09-24 本人指示）: 3つの列（シーン／台本／選んだセリフ）の横幅をドラッグで変える ----------
   * 見た目と操作は舞台タブのパネル列の取っ手（stage-sketch.js の initPanelWidths・.stage-panel-width-handle）と同じ:
   * ドラッグで幅を変える／左右キーで10px（Shift で30px）／Home・End で最小・最大／ダブルクリックまたは Enter で元に戻す。
   * 変えるのは両端の列（シーン・選んだセリフ）。台本は残りを使う（最小360px・CSSの上限1100px）。
   * 右列は本文の上限を超える余りも受け取る。保存する希望幅と実際の列幅は分ける。
   * 端末の設定（gamma:script-editor-widths-v1）。数値: 既定 シーン292px・選んだセリフ320px／シーン 180〜480px・選んだセリフ 240〜560px。
   * J3: 余りだけで560pxを超える画面では、右列を本文の最小360pxを残せる幅まで広げられる。 */
  const WIDTH_KEY = "gamma:script-editor-widths-v1";
  const WIDTH_DEFAULT = { scenes: 292, inspector: 320 };
  const WIDTH_LIMIT = { scenes: [180, 480], inspector: [240, 560] };
  const SCRIPT_MIN = 360;
  let columnWidths = { ...WIDTH_DEFAULT };
  try { const saved = JSON.parse(localStorage.getItem(WIDTH_KEY) || "null"); if (saved && typeof saved === "object") columnWidths = { ...WIDTH_DEFAULT, ...saved }; } catch (_) { /* 既定のまま */ }
  function maxColumnWidth(key, body) {
    const max = WIDTH_LIMIT[key][1];
    if (key !== "inspector" || !body) return max;
    const scenes = Math.max(WIDTH_LIMIT.scenes[0], Math.min(WIDTH_LIMIT.scenes[1], Number(columnWidths.scenes) || WIDTH_DEFAULT.scenes));
    const textMax = parseFloat(getComputedStyle(body).getPropertyValue("--script-ed-text-max"));
    const available = body.clientWidth - scenes - 16;
    // 実幅が既存の上限を超えたときも、掴んだ場所から広げられるようにする。
    return available - textMax > max || Number(columnWidths.inspector) > max ? Math.max(max, available - SCRIPT_MIN) : max;
  }
  function clampWidth(key, value, body) {
    const [min] = WIDTH_LIMIT[key];
    const maxBase = maxColumnWidth(key, body);
    // 広い画面で保存した大きな右列幅で、狭い画面の左列まで縮めない。
    const other = key === "scenes" ? Math.min(WIDTH_LIMIT.inspector[1], Number(columnWidths.inspector) || WIDTH_DEFAULT.inspector) : columnWidths.scenes;
    const room = body ? body.clientWidth - other - SCRIPT_MIN - 16 : maxBase;
    return Math.round(Math.max(min, Math.min(maxBase, room, value)));
  }
  function applyColumnWidths(body) {
    if (!body) return;
    const scenes = clampWidth("scenes", Number(columnWidths.scenes) || WIDTH_DEFAULT.scenes, body);
    const inspector = clampWidth("inspector", Number(columnWidths.inspector) || WIDTH_DEFAULT.inspector, body);
    body.style.setProperty("--script-ed-scenes-width", `${scenes}px`);
    body.style.setProperty("--script-ed-inspector-width", `${inspector}px`);
    const bodyRect = body.getBoundingClientRect();
    if (!bodyRect.width) return;
    const boxes = [...body.querySelectorAll(":scope > .script-ed-box")].map((box) => box.getBoundingClientRect());
    body.querySelectorAll(".stage-panel-width-handle").forEach((handle) => {
      const key = handle.dataset.scriptWidth;
      const index = key === "scenes" ? 0 : 2;
      // 列間の真ん中を実測する。余り・スクロールバー・端数があっても境界から離れない。
      const boundary = key === "scenes" ? (boxes[0].right + boxes[1].left) / 2 : (boxes[1].right + boxes[2].left) / 2;
      handle.style.setProperty("--script-ed-boundary", `${boundary - bodyRect.left}px`);
      handle.setAttribute("aria-valuemin", String(WIDTH_LIMIT[key][0]));
      handle.setAttribute("aria-valuemax", String(Math.max(maxColumnWidth(key, body), boxes[index].width)));
      handle.setAttribute("aria-valuenow", String(boxes[index].width));
    });
  }
  function saveColumnWidths() {
    try { localStorage.setItem(WIDTH_KEY, JSON.stringify(columnWidths)); } catch (_) { /* 残せなくても、この画面では効かせる */ }
  }
  function mountColumnHandles(body, scenesBox, inspectorBox) {
    [[scenesBox, "scenes", "left", tx("シーンの列の幅")], [inspectorBox, "inspector", "right", tx("選んだセリフの列の幅")]].forEach(([box, key, side, name]) => {
      const handle = el("div", "stage-panel-width-handle");
      handle.dataset.panelWidth = side;       // 舞台タブと同じ見た目（左の列は右端・右の列は左端に付く）
      handle.dataset.scriptWidth = key;
      handle.tabIndex = 0;
      handle.setAttribute("role", "separator");
      handle.setAttribute("aria-orientation", "vertical");
      handle.setAttribute("aria-label", name);
      handle.title = tx("ドラッグで幅を変更。左右キーで調整、ダブルクリックまたはEnterで元に戻す");
      const grip = el("span");
      grip.setAttribute("aria-hidden", "true");
      handle.append(grip);
      // 取っ手は列ではなく3列の外枠に付ける（「選んだセリフ」は中身がスクロールするので、列に付けると切り取られる）
      body.append(handle);
      const direction = key === "inspector" ? -1 : 1;
      const hasSurplus = () => key === "inspector" && box.getBoundingClientRect().width > parseFloat(body.style.getPropertyValue("--script-ed-inspector-width")) + 0.5;
      let drag = null;
      handle.addEventListener("pointerdown", (event) => {
        if (event.button !== 0 || event.isPrimary === false) return;
        event.preventDefault(); event.stopPropagation();
        drag = { pointerId: event.pointerId, startX: event.clientX, start: box.getBoundingClientRect().width,
          preferred: columnWidths[key], surplus: hasSurplus() };
        handle.setPointerCapture(event.pointerId);
        handle.focus({ preventScroll: true });
        document.body.classList.add("is-panel-resizing");
      });
      handle.addEventListener("pointermove", (event) => {
        if (!drag || event.pointerId !== drag.pointerId) return;
        event.preventDefault();
        const next = drag.start + direction * (event.clientX - drag.startX);
        // 余りのため動かせない範囲では、元の希望幅も増やさない。広げてから戻した場合も同じ。
        columnWidths[key] = drag.surplus && next <= drag.start ? drag.preferred : clampWidth(key, next, body);
        applyColumnWidths(body);
      });
      const end = (commit) => {
        if (!drag) return;
        drag = null;
        document.body.classList.remove("is-panel-resizing");
        if (commit) saveColumnWidths();
      };
      handle.addEventListener("pointerup", () => end(true));
      handle.addEventListener("pointercancel", () => end(true));
      handle.addEventListener("lostpointercapture", () => end(true));
      const reset = () => { columnWidths[key] = WIDTH_DEFAULT[key]; applyColumnWidths(body); saveColumnWidths(); };
      handle.addEventListener("dblclick", (event) => { event.preventDefault(); reset(); });
      handle.addEventListener("keydown", (event) => {
        if (!["ArrowLeft", "ArrowRight", "Home", "End", "Enter"].includes(event.key)) return;
        event.preventDefault(); event.stopPropagation();
        if (event.key === "Enter") { reset(); return; }
        const [min] = WIDTH_LIMIT[key];
        const max = maxColumnWidth(key, body);
        const step = (event.key === "ArrowRight" ? 1 : -1) * direction * (event.shiftKey ? 30 : 10);
        if (event.key.startsWith("Arrow") && step < 0 && hasSurplus()) return;
        const next = event.key === "Home" ? min : event.key === "End" ? max : box.getBoundingClientRect().width + step;
        columnWidths[key] = clampWidth(key, next, body);
        applyColumnWidths(body); saveColumnWidths();
      });
    });
    applyColumnWidths(body);
    if (typeof ResizeObserver === "function") new ResizeObserver(() => applyColumnWidths(body)).observe(body);
  }

  /* ---------- 描画 ---------- */

  // 骨組みは初回だけ作る。言語を変えたときも同じボタン・入力欄を使って文字を更新する。
  function syncChromeLanguage() {
    if (!ui.body) return;
    ui.exportScript.textContent = tx("台本を書き出す");
    ui.exportScript.title = tx("A4の印刷用の窓で開きます（印刷・PDF保存）");
    ui.reimport.textContent = tx("シーンメモから取り込み直す");
    ui.addLine.textContent = tx("＋ 行を足す");
    ui.search.placeholder = tx("セリフ・話者で探す");
    ui.search.setAttribute("aria-label", tx("セリフ・話者で探す"));
    for (const [selector, label] of [[".script-ed-scenes", "シーン"], [".script-ed-script", "台本"]]) {
      const box = ui.body.querySelector(selector);
      box.setAttribute("aria-label", tx(label));
      box.querySelector(".script-ed-title").textContent = tx(label);
    }
    ui.body.querySelector(".script-ed-script-head .script-ed-hint").textContent = tx("行を押して選ぶ。ダブルクリックでその場で直す。⠿ を持って並べ替え（Alt＋↑↓でも動かせます）。");
    ui.lines.setAttribute("aria-label", tx("台本の行"));
    ui.inspector.setAttribute("aria-label", tx("選んだセリフ"));
    ui.body.querySelectorAll("[data-script-width]").forEach((handle) => {
      handle.setAttribute("aria-label", tx(handle.dataset.scriptWidth === "scenes" ? "シーンの列の幅" : "選んだセリフの列の幅"));
      handle.title = tx("ドラッグで幅を変更。左右キーで調整、ダブルクリックまたはEnterで元に戻す");
    });
  }

  function render() {
    if (!isOpen) return;
    if (!ui.body) build();
    syncChromeLanguage();
    const hasScript = Boolean(script);
    ui.body.hidden = !hasScript;
    ui.empty.hidden = hasScript;
    ui.reimport.hidden = !hasScript;
    ui.addLine.hidden = !hasScript;
    ui.addLine.disabled = !hasScript || !sceneRows().length;
    ui.exportScript.disabled = !hasScript || !script.lines.length;
    if (!hasScript) { renderEmpty(); renderSummary(); return; }
    if (selectedId && !script.lines.some((line) => line.id === selectedId)) selectedId = null;
    renderSummary();
    renderToc();
    renderLines();
    renderInspector();
  }

  function renderSummary() {
    if (!script) {
      ui.summary.textContent = tx("台本はまだありません");
      return;
    }
    const assigned = script.lines.filter((line) => line.cueId).length;
    const cueless = voxCues.filter((cue) => !lineForCue(cue.id)).length;
    ui.summary.textContent = "";
    ui.summary.append(el("b", null, `${tx("台本")} ${script.lines.length}${tx("行")}`),
      el("span", null, ` · ${tx("キューに割り当て済み")} ${assigned}`),
      el("span", cueless ? "is-warn" : null, ` · ${tx("行のないセリフキュー")} ${cueless}`));
  }

  function renderEmpty() {
    ui.empty.textContent = "";
    const box = el("div", "script-ed-empty-box");
    const count = countNoteLines();
    box.append(el("h2", "script-ed-title", tx("このショーの台本はまだありません")),
      el("p", "script-ed-hint", count
        ? tx("シーンメモの【台本】に書かれたセリフを取り込めます。シーンメモは消さずに残ります。")
        : tx("シーンメモに【台本】の行が見つかりません。空の台本から始めて、行を足していけます。")));
    const acts = el("div", "script-ed-actions");
    if (count) {
      const take = el("button", "script-ed-btn primary", `${tx("シーンメモから取り込む")}（${count}${tx("行")}）`);
      take.type = "button";
      take.addEventListener("click", () => { script = buildFromNotes(); commit(); render(); });
      acts.append(take);
    }
    const blank = el("button", "script-ed-btn", tx("空の台本から始める"));
    blank.type = "button";
    blank.disabled = !sceneRows().length;
    blank.addEventListener("click", () => { script = { version: 1, lines: [] }; commit(); render(); });
    acts.append(blank);
    box.append(acts);
    ui.empty.append(box);
  }

  function renderToc() {
    const numbers = sceneNumbers();
    ui.toc.textContent = "";
    scenes().forEach((row) => {
      const item = el("li", row.kind === "section" ? "script-ed-toc-section" : "script-ed-toc-scene");
      item.style.setProperty("--depth", String(Math.max(0, Number(row.depth) || 0)));
      if (row.kind === "section") {
        item.append(el("span", null, `${numbers.get(row.id) || ""}  ${row.title || tx("セクション")}`));
      } else {
        const button = el("button", "script-ed-toc-button");
        button.type = "button";
        const count = script.lines.filter((line) => line.sceneId === row.id).length;
        button.append(el("span", "script-ed-toc-no", numbers.get(row.id) || ""),
          el("span", "script-ed-toc-name", row.title || tx("シーン")),
          el("span", count ? "script-ed-toc-count" : "script-ed-toc-count is-zero", String(count)));
        button.addEventListener("click", () => {
          const group = ui.lines.querySelector(`[data-scene-group="${CSS.escape(row.id)}"]`);
          if (group) ui.lines.scrollTop = group.offsetTop - ui.lines.offsetTop;
        });
        item.append(button);
      }
      ui.toc.append(item);
    });
  }

  // ト書き（括弧内）を小さく別の色で（セリフキューパネルと同じ分け方）
  function lineTextNode(text) {
    const span = el("span", "script-ed-row-text");
    const api = panelApi();
    const parts = api ? api.splitDirections(text) : [{ text, direction: false }];
    if (!text) { span.classList.add("is-missing"); span.textContent = tx("（まだ何も書かれていません）"); return span; }
    parts.forEach((part) => {
      if (!part.direction) { span.append(document.createTextNode(part.text)); return; }
      span.append(el("span", "script-ed-direction", part.text));
    });
    return span;
  }

  function speakerNode(line) {
    const who = speakerOf(line);
    const span = el("span", "script-ed-row-speaker");
    if (who.color) {
      const chip = el("span", "script-ed-chip");
      chip.style.background = who.color;
      chip.setAttribute("aria-hidden", "true");
      span.append(chip);
    }
    span.append(document.createTextNode(who.name || tx("話者なし")));
    if (!who.name) span.classList.add("is-missing");
    return span;
  }

  function matches(line) {
    if (!query) return true;
    const q = query.toLowerCase();
    return `${speakerOf(line).name} ${line.text}`.toLowerCase().includes(q);
  }

  function renderLines() {
    if (!script || !ui.lines) return;
    const numbers = sceneNumbers();
    const keepScroll = ui.lines.scrollTop;
    ui.lines.textContent = "";
    const groups = sceneRows().map((scene) => ({ scene, lines: script.lines.filter((line) => line.sceneId === scene.id) }));
    const orphans = script.lines.filter((line) => !sceneRows().some((scene) => scene.id === line.sceneId));
    if (orphans.length) groups.push({ scene: null, lines: orphans });
    groups.forEach(({ scene, lines }) => {
      const group = el("div", "script-ed-group");
      group.dataset.sceneGroup = scene ? scene.id : "";
      const head = el("div", "script-ed-group-head");
      head.append(el("span", "script-ed-group-no", scene ? numbers.get(scene.id) || "" : "—"),
        el("span", "script-ed-group-title", scene ? scene.title || tx("シーン") : tx("シーンなし（シーンが消えた行）")));
      if (scene) {
        const add = el("button", "script-ed-btn small", tx("＋ このシーンに行を足す"));
        add.type = "button";
        add.dataset.tipDescription = "このシーンの台本の末尾に新しい行を追加します。";
        add.addEventListener("click", () => addLineToScene(scene.id));
        head.append(add);
      }
      group.append(head);
      // このシーンの、まだ行のないセリフキュー（押すと、そのシーンの新しい行に割り当てる）
      if (scene) {
        const free = voxCues.filter((cue) => cue.sceneId === scene.id && !lineForCue(cue.id));
        if (free.length) {
          const strip = el("div", "script-ed-free");
          strip.append(el("span", "script-ed-free-label", tx("行のないキュー")));
          free.forEach((cue) => {
            const chip = el("button", "script-ed-cue-chip is-free", cue.displayName);
            chip.type = "button";
            chip.title = tx("このキューに新しい行を作る");
            chip.addEventListener("click", () => addLineToScene(scene.id, cue.id));
            strip.append(chip);
          });
          group.append(strip);
        }
      }
      let lastSeconds = -Infinity;
      lines.forEach((line, index) => {
        const row = el("div", "script-ed-row");
        row.dataset.lineId = line.id;
        row.setAttribute("role", "option");
        row.setAttribute("aria-selected", String(line.id === selectedId));
        if (line.id === selectedId) row.classList.add("is-selected");
        if (!matches(line)) row.hidden = true;
        const grip = el("span", "script-ed-grip", "⠿");
        grip.setAttribute("aria-hidden", "true");
        grip.addEventListener("pointerdown", (event) => startDrag(event, line.id, row));
        const no = el("span", "script-ed-row-no", String(index + 1));
        const cue = line.cueId ? cueById(line.cueId) : null;
        const cueChip = el("span", cue ? "script-ed-cue-chip" : "script-ed-cue-chip is-none",
          cue ? cue.displayName : tx("キューなし"));
        // 同じシーンで、キューの時刻の順と行の順が逆になっていたら知らせる
        if (cue) {
          if (cue.seconds < lastSeconds) { cueChip.classList.add("is-out-of-order"); cueChip.title = tx("キューの時刻の順と、行の順が逆になっています"); }
          lastSeconds = Math.max(lastSeconds, cue.seconds);
        }
        const main = el("span", "script-ed-row-main");
        const who = speakerNode(line);
        // 元の台本で「新規セリフの提案」とされている行（本人採用済みという意味ではない）
        if (line.origin === "new_dialogue_proposal") {
          const tag = el("span", "script-ed-proposal", tx("提案"));
          tag.title = tx("元の台本で「新規セリフの提案」とされている行です（採用済みのセリフという意味ではありません）");
          who.append(tag);
        }
        main.append(who, lineTextNode(line.text));
        row.append(grip, no, main, cueChip);
        row.addEventListener("click", () => { if (!row.classList.contains("is-inline-editing")) select(line.id); });
        row.addEventListener("dblclick", (event) => {
          if (event.target.closest(".script-ed-grip")) return;
          event.preventDefault();
          startInlineEdit(line.id, row);
        });
        group.append(row);
      });
      if (!lines.length) group.append(el("p", "script-ed-group-empty", tx("このシーンにはまだ行がありません")));
      ui.lines.append(group);
    });
    ui.lines.scrollTop = keepScroll;
  }

  function sceneOptions(select, value) {
    const numbers = sceneNumbers();
    sceneRows().forEach((scene) => {
      const option = el("option", null, `${numbers.get(scene.id) || ""}  ${scene.title || tx("シーン")}`);
      option.value = scene.id;
      option.selected = scene.id === value;
      select.append(option);
    });
  }

  function field(labelText, control, hint) {
    const wrap = el("label", "script-ed-field");
    wrap.append(el("span", "script-ed-label", labelText), control);
    if (hint) wrap.append(el("span", "script-ed-hint", hint));
    return wrap;
  }

  function renderInspector() {
    const box = ui.inspector;
    box.textContent = "";
    box.append(el("h2", "script-ed-title", tx("選んだセリフ")));
    const line = script && script.lines.find((item) => item.id === selectedId);
    if (!line) {
      box.append(el("p", "script-ed-hint", tx("中央の台本から行を選ぶと、ここで話者・セリフ・シーン・キューを直せます。")));
      return;
    }
    // 話者: 演者から選ぶ＋自由入力（本人決定）
    const who = el("select", "script-ed-input");
    const none = el("option", null, tx("（話者なし）")); none.value = ""; who.append(none);
    cast().forEach((member) => {
      const option = el("option", null, member.name); option.value = member.id;
      option.selected = line.castId === member.id; who.append(option);
    });
    const other = el("option", null, tx("その他（名前を書く）")); other.value = OTHER_SPEAKER; who.append(other);
    if (!line.castId) who.value = line.speaker ? OTHER_SPEAKER : "";
    const free = el("input", "script-ed-input");
    free.type = "text"; free.maxLength = 40; free.value = line.castId ? "" : line.speaker || "";
    free.placeholder = tx("例: 大道具さん");
    free.hidden = who.value !== OTHER_SPEAKER;
    who.addEventListener("change", () => {
      if (who.value === OTHER_SPEAKER) { line.castId = null; free.hidden = false; free.focus(); }
      else { line.castId = who.value || null; line.speaker = ""; free.hidden = true; }
      commit(); renderLines(); renderSummary();
    });
    free.addEventListener("input", () => { line.castId = null; line.speaker = free.value; scheduleCommit(); });
    const whoWrap = el("div", "script-ed-stack"); whoWrap.append(who, free);
    box.append(field(tx("話者"), whoWrap, tx("演者から選ぶと、名前と色が演者と同じになります。")));

    // セリフ
    const text = el("textarea", "script-ed-input script-ed-textarea");
    text.value = line.text || ""; text.rows = 6; text.maxLength = 4000;
    text.addEventListener("input", () => { line.text = text.value; scheduleCommit(); });
    text.addEventListener("keydown", (event) => {
      // ⌘/Ctrl＋Enter で、この下に新しい行を足す
      if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) { event.preventDefault(); addLineAfter(line.id); }
    });
    ui.textArea = text;
    box.append(field(tx("セリフ"), text, tx("括弧（ ）で囲んだ部分はト書きとして小さく出ます。⌘＋Enterで下に行を足す。")));
    if (line.origin === "new_dialogue_proposal") {
      box.append(el("p", "script-ed-hint script-ed-proposal-note", tx("この行は元の台本で「新規セリフの提案」とされています。採用済みのセリフという意味ではありません。")));
    }

    // シーン
    const scene = el("select", "script-ed-input");
    sceneOptions(scene, line.sceneId);
    scene.addEventListener("change", () => {
      const moved = moveLineToScene(line.id, scene.value);
      if (moved) { commit(); render(); }
    });
    box.append(field(tx("シーン"), scene));

    // キュー（1キュー＝1行）
    const cueSelect = el("select", "script-ed-input");
    const noCue = el("option", null, tx("割り当てなし")); noCue.value = ""; cueSelect.append(noCue);
    voxCues.filter((cue) => cue.sceneId === line.sceneId).forEach((cue) => {
      const owner = lineForCue(cue.id);
      const taken = owner && owner.id !== line.id;
      const option = el("option", null, `${cue.displayName}  ${formatTime(cue.seconds)}${taken ? `（${tx("別の行で使用中")}）` : ""}`);
      option.value = cue.id; option.selected = line.cueId === cue.id;
      cueSelect.append(option);
    });
    cueSelect.addEventListener("change", () => { assignCue(line.id, cueSelect.value || null); });
    const newCue = el("button", "script-ed-btn small", tx("新しいセリフキューを作って割り当てる"));
    newCue.type = "button";
    newCue.disabled = !line.sceneId;
    newCue.addEventListener("click", () => createCueFor(line.id));
    const cueWrap = el("div", "script-ed-stack"); cueWrap.append(cueSelect, newCue);
    box.append(field(tx("キュー"), cueWrap, tx("1つのセリフキューに1行。別の行で使っているキューを選ぶと、その行から外れます。")));

    // 並び・削除
    const order = el("div", "script-ed-row-actions");
    const up = el("button", "script-ed-btn small", tx("↑ 上へ")); up.type = "button";
    const down = el("button", "script-ed-btn small", tx("↓ 下へ")); down.type = "button";
    up.addEventListener("click", () => nudge(line.id, -1));
    down.addEventListener("click", () => nudge(line.id, 1));
    const remove = el("button", "script-ed-btn small quiet danger", tx("この行を削除")); remove.type = "button";
    remove.addEventListener("click", () => removeLine(line.id));
    order.append(up, down, remove);
    box.append(order);
    box.append(el("p", "script-ed-hint", tx("行を削除しても、割り当てていたセリフキューは残ります（キューのメモが表示に使われます）。取り消しは画面上部の「一つ戻す」で。")));
  }

  /* ---------- U-10（2026-09-24 本人指示）: ダブルクリックでその場で直す ----------
   * 行のセリフの文字を、その場の入力欄に替える。Enter で確定・Shift＋Enter で改行・Esc で取り消し・欄の外を押しても確定。
   * 確定は右の欄と同じ書き込み（commit＝取り消し1回で戻る単位）。右の「選んだセリフ」はそのまま残す（本人指定）。
   * 数値: 欄は行の本文と同じ明朝15px・行間1.6・1px真鍮の枠・最小2行・中身に合わせて伸びる（最大10行）。 */
  let inlineEdit = null;
  function startInlineEdit(lineId, row) {
    const line = script && script.lines.find((item) => item.id === lineId);
    if (!line || !row) return;
    if (inlineEdit) finishInlineEdit(true);
    if (selectedId !== lineId) select(lineId);
    const target = ui.lines.querySelector(`.script-ed-row[data-line-id="${CSS.escape(lineId)}"]`) || row;
    const shown = target.querySelector(".script-ed-row-text");
    if (!shown) return;
    const input = el("textarea", "script-ed-inline");
    input.value = line.text || "";
    input.rows = 2;
    input.maxLength = 4000;
    input.setAttribute("aria-label", tx("セリフ"));
    const fit = () => { input.style.height = "auto"; input.style.height = `${Math.min(input.scrollHeight, 15 * 1.6 * 10 + 14)}px`; };
    shown.replaceWith(input);
    target.classList.add("is-inline-editing");
    inlineEdit = { lineId, input, before: line.text || "" };
    input.addEventListener("input", fit);
    input.addEventListener("keydown", (event) => {
      event.stopPropagation();   // 一覧の↑↓・舞台側のショートカットへ渡さない
      if (event.isComposing) return;
      if (event.key === "Escape") { event.preventDefault(); finishInlineEdit(false); ui.lines.focus({ preventScroll: true }); }
      else if (event.key === "Enter" && !event.shiftKey) { event.preventDefault(); finishInlineEdit(true); ui.lines.focus({ preventScroll: true }); }
    });
    input.addEventListener("blur", () => finishInlineEdit(true));
    input.addEventListener("dblclick", (event) => event.stopPropagation());
    input.addEventListener("click", (event) => event.stopPropagation());
    fit();
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
  }
  function finishInlineEdit(save) {
    const edit = inlineEdit;
    if (!edit) return;
    inlineEdit = null;
    const line = script && script.lines.find((item) => item.id === edit.lineId);
    if (line && save && edit.input.value !== edit.before) {
      line.text = edit.input.value;
      commit();
    }
    renderLines();
    renderSummary();
    if (line && selectedId === line.id) renderInspector();
  }

  function formatTime(seconds) {
    const total = Math.max(0, Math.floor(Number(seconds) || 0));
    return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, "0")}`;
  }

  /* ---------- 操作 ---------- */

  function select(id, focusList = false) {
    flushTextTimer();
    selectedId = id;
    ui.lines.querySelectorAll(".script-ed-row").forEach((row) => {
      const on = row.dataset.lineId === id;
      row.classList.toggle("is-selected", on);
      row.setAttribute("aria-selected", String(on));
      if (on) {
        const top = row.offsetTop - ui.lines.offsetTop;
        if (top < ui.lines.scrollTop) ui.lines.scrollTop = top - 40;
        else if (top + row.offsetHeight > ui.lines.scrollTop + ui.lines.clientHeight) ui.lines.scrollTop = top + row.offsetHeight - ui.lines.clientHeight + 8;
      }
    });
    renderInspector();
    if (focusList) ui.lines.focus({ preventScroll: true });
  }

  function scheduleCommit() {
    pendingText = true;
    clearTimeout(commitTimer);
    commitTimer = setTimeout(() => { commitTimer = 0; pendingText = null; commit(); renderLines(); renderSummary(); }, 450);
  }

  // 表示の順（シーンの順→同じシーンは配列の順）に並べた行
  function displayOrder() {
    const order = [];
    sceneRows().forEach((scene) => script.lines.forEach((line) => { if (line.sceneId === scene.id) order.push(line); }));
    script.lines.forEach((line) => { if (!order.includes(line)) order.push(line); });
    return order;
  }

  function newLine(sceneId, cueId = null) {
    return { id: rid(), sceneId, castId: null, speaker: "", text: "", cueId };
  }

  function addLineToScene(sceneId, cueId = null) {
    if (!script) return;
    const line = newLine(sceneId, cueId);
    const last = [...script.lines].reverse().find((item) => item.sceneId === sceneId);
    const at = last ? script.lines.indexOf(last) + 1 : script.lines.length;
    script.lines.splice(at, 0, line);
    commit();
    selectedId = line.id;
    render();
    if (ui.textArea) ui.textArea.focus();
  }

  function addLineAfter(lineId) {
    if (!script) return;
    const anchor = script.lines.find((line) => line.id === lineId);
    const sceneId = anchor ? anchor.sceneId : (project && project.activeSceneId) || (sceneRows()[0] && sceneRows()[0].id);
    if (!sceneId) return;
    const line = newLine(sceneId);
    if (anchor) {
      // 話者は前の行と入れ替わることが多いので、空のまま（選び直す手間を増やさない）
      script.lines.splice(script.lines.indexOf(anchor) + 1, 0, line);
    } else {
      script.lines.push(line);
    }
    commit();
    selectedId = line.id;
    render();
    if (ui.textArea) ui.textArea.focus();
  }

  function removeLine(lineId) {
    const at = script.lines.findIndex((line) => line.id === lineId);
    if (at < 0) return;
    const order = displayOrder();
    const index = order.findIndex((line) => line.id === lineId);
    const nextSel = order[index + 1] || order[index - 1] || null;
    script.lines.splice(at, 1);
    commit();
    selectedId = nextSel ? nextSel.id : null;
    render();
  }

  // 別のシーンへ移すと、そのシーンにないキューからは外す
  function moveLineToScene(lineId, sceneId) {
    const line = script.lines.find((item) => item.id === lineId);
    if (!line || line.sceneId === sceneId) return false;
    const at = script.lines.indexOf(line);
    script.lines.splice(at, 1);
    line.sceneId = sceneId;
    const cue = line.cueId ? cueById(line.cueId) : null;
    if (cue && cue.sceneId !== sceneId) line.cueId = null;
    const last = [...script.lines].reverse().find((item) => item.sceneId === sceneId);
    script.lines.splice(last ? script.lines.indexOf(last) + 1 : script.lines.length, 0, line);
    return true;
  }

  // 表示の順で1つ上／下へ。シーンの端では隣のシーンへ移る
  function nudge(lineId, direction) {
    const order = displayOrder();
    const index = order.findIndex((line) => line.id === lineId);
    const target = order[index + direction];
    if (index < 0 || !target) return;
    const line = order[index];
    if (target.sceneId !== line.sceneId) {
      // 隣のシーンの端へ
      script.lines.splice(script.lines.indexOf(line), 1);
      line.sceneId = target.sceneId;
      const cue = line.cueId ? cueById(line.cueId) : null;
      if (cue && cue.sceneId !== line.sceneId) line.cueId = null;
      const at = script.lines.indexOf(target) + (direction > 0 ? 0 : 1);
      script.lines.splice(at, 0, line);
    } else {
      const a = script.lines.indexOf(line);
      const b = script.lines.indexOf(target);
      script.lines[a] = target;
      script.lines[b] = line;
    }
    commit();
    render();
  }

  function assignCue(lineId, cueId) {
    const line = script.lines.find((item) => item.id === lineId);
    if (!line) return;
    if (cueId) script.lines.forEach((item) => { if (item.id !== lineId && item.cueId === cueId) item.cueId = null; });
    line.cueId = cueId;
    commit();
    render();
  }

  /* そのシーンに新しいセリフキューを作って割り当てる。置く位置は、そのシーンの最後のセリフキューの3秒後
   * （無ければシーンの頭から1秒）。シーン＋オフセットの形なので、セクションの時間を変えてもシーンから外れない。 */
  function createCueFor(lineId) {
    const line = script.lines.find((item) => item.id === lineId);
    if (!line || !line.sceneId) return;
    const scene = sceneRows().find((row) => row.id === line.sceneId);
    const hold = Math.max(1, Number(scene && scene.rehearsal && scene.rehearsal.holdDurationSeconds) || 10);
    const offsets = (project.cues || []).filter((cue) => cue && cue.cueType === "dialogue" && cue.sceneId === line.sceneId
      && Number.isFinite(Number(cue.offsetSeconds))).map((cue) => Number(cue.offsetSeconds));
    const offset = Math.min(Math.max(0, hold - 0.5), offsets.length ? Math.max(...offsets) + 3 : 1);
    const cueId = `cue-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
    script.lines.forEach((item) => { if (item.id !== lineId && item.cueId === cueId) item.cueId = null; });
    line.cueId = cueId;
    commit({ addCues: [{ id: cueId, sceneId: line.sceneId, offsetSeconds: offset }] });
    render();
  }

  async function reimport() {
    const basis = JSON.stringify(script);
    const projectId = project?.id;
    const count = countNoteLines();
    const message = tx("いまの台本を消して、シーンメモの【台本】から取り込み直します。台本で直した文字・並び・割り当ては失われます（「一つ戻す」で戻せます）。")
      + `\n${tx("取り込む行数")}: ${count}`;
    if (!await window.GAMMA_SURFACE_DIALOG.confirm(message) || project?.id !== projectId || JSON.stringify(script) !== basis) return;
    script = buildFromNotes();
    commit();
    selectedId = null;
    render();
  }

  function onListKey(event) {
    if (!script) return;
    const order = displayOrder().filter(matches);
    const index = order.findIndex((line) => line.id === selectedId);
    if ((event.key === "ArrowUp" || event.key === "ArrowDown") && event.altKey && selectedId) {
      event.preventDefault();
      nudge(selectedId, event.key === "ArrowUp" ? -1 : 1);
      ui.lines.focus({ preventScroll: true });
      return;
    }
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const next = order[index < 0 ? 0 : index + (event.key === "ArrowDown" ? 1 : -1)];
      if (next) select(next.id, true);
      return;
    }
    if (event.key === "Enter" && selectedId && ui.textArea) {
      event.preventDefault();
      ui.textArea.focus();
    }
  }

  /* ---------- 並べ替え（⠿ を持って動かす。タッチでも動くようポインタで自前に持つ） ----------
   * U-12（2026-09-24 本人指示）: 掴んだ行は指に付いて動き、ほかの行は滑って場所を空ける（iPhoneのホーム画面と同じ手触り）。
   * シーンをまたいで動かせる（行の無いシーンへは、そのシーンの欄の空いている所へ落とす）。
   * 並びの確定は放したとき。画面の行の並びから「前の行／シーン」を読み取って、台本データへ写す。 */

  function rowSlot(other) {
    const box = other.getBoundingClientRect();
    const matrix = getComputedStyle(other).transform;
    const dy = matrix && matrix !== "none" && typeof DOMMatrixReadOnly === "function" ? new DOMMatrixReadOnly(matrix).m42 : 0;
    return { top: box.top - dy, height: box.height };
  }

  function startDrag(event, lineId, row) {
    if (event.button !== undefined && event.button > 0) return;
    event.preventDefault();
    flushTextTimer();
    if (inlineEdit) finishInlineEdit(true);
    const motion = window.SHOSAI_REORDER_MOTION;
    dragging = { lineId, row, moved: false, startY: event.clientY, grabY: event.clientY - row.getBoundingClientRect().top };
    const move = (ev) => {
      if (!dragging) return;
      if (!dragging.moved) {
        if (Math.abs(ev.clientY - dragging.startY) < 4) return;
        dragging.moved = true;
        row.classList.add("is-dragging");
      }
      const rows = [...ui.lines.querySelectorAll(".script-ed-row")].filter((other) => !other.hidden);
      const groups = [...ui.lines.querySelectorAll(".script-ed-group")];
      const moving = [...rows, ...groups.map((group) => group.querySelector(".script-ed-group-empty")).filter(Boolean)];
      const overRow = rows.find((other) => {
        if (other === row) return false;
        const box = rowSlot(other);
        return ev.clientY >= box.top && ev.clientY <= box.top + box.height;
      });
      let place = null;
      if (overRow) {
        const box = rowSlot(overRow);
        const before = ev.clientY < box.top + box.height / 2;
        const reference = before ? overRow : overRow.nextSibling;
        if (reference !== row && row.nextSibling !== reference) place = () => overRow.parentNode.insertBefore(row, reference);
      } else {
        // 行の上に居ないとき: 指の下のシーンの欄（行の無いシーンを含む）の末尾へ
        const group = groups.find((item) => {
          const box = item.getBoundingClientRect();
          return item.dataset.sceneGroup && ev.clientY >= box.top && ev.clientY <= box.bottom;
        });
        if (group && row.parentNode !== group) {
          const empty = group.querySelector(".script-ed-group-empty");
          place = () => { if (empty) empty.hidden = true; group.append(row); };
        }
      }
      if (place) {
        if (motion) motion.flip(moving, place, row); else place();
        // 元のシーンが空になったら「まだ行がありません」を戻す
        groups.forEach((item) => {
          const empty = item.querySelector(".script-ed-group-empty");
          if (empty) empty.hidden = Boolean(item.querySelector(".script-ed-row"));
        });
      }
      if (motion) motion.follow(row, ev.clientY, dragging.grabY);
      // 端へ近づいたら一覧を送る
      const box = ui.lines.getBoundingClientRect();
      if (ev.clientY < box.top + 30) ui.lines.scrollTop -= 12;
      else if (ev.clientY > box.bottom - 30) ui.lines.scrollTop += 12;
    };
    const up = () => {
      document.removeEventListener("pointermove", move);
      document.removeEventListener("pointerup", up);
      document.removeEventListener("pointercancel", up);
      row.classList.remove("is-dragging");
      const drag = dragging;
      dragging = null;
      if (motion) motion.settle(row);
      if (drag && drag.moved) window.setTimeout(() => dropLine(drag), motion ? motion.MS : 0);
    };
    document.addEventListener("pointermove", move);
    document.addEventListener("pointerup", up);
    document.addEventListener("pointercancel", up);
  }

  // 画面に並んだ行の順（シーンの欄ごと）を、台本データの並びへ写す。掴んだ行だけが動いている。
  function dropLine(drag) {
    const line = script.lines.find((item) => item.id === drag.lineId);
    if (!line || !drag.row.isConnected) { render(); return; }
    const group = drag.row.closest(".script-ed-group");
    const sceneId = group && group.dataset.sceneGroup ? group.dataset.sceneGroup : line.sceneId;
    let previous = drag.row.previousElementSibling;
    while (previous && !previous.classList.contains("script-ed-row")) previous = previous.previousElementSibling;
    let following = drag.row.nextElementSibling;
    while (following && !following.classList.contains("script-ed-row")) following = following.nextElementSibling;
    script.lines.splice(script.lines.indexOf(line), 1);
    const prevLine = previous ? script.lines.find((item) => item.id === previous.dataset.lineId) : null;
    const nextLine = following ? script.lines.find((item) => item.id === following.dataset.lineId) : null;
    line.sceneId = sceneId;
    if (prevLine) script.lines.splice(script.lines.indexOf(prevLine) + 1, 0, line);
    else if (nextLine) script.lines.splice(script.lines.indexOf(nextLine), 0, line);
    else {
      const last = [...script.lines].reverse().find((item) => item.sceneId === sceneId);
      script.lines.splice(last ? script.lines.indexOf(last) + 1 : script.lines.length, 0, line);
    }
    const cue = line.cueId ? cueById(line.cueId) : null;
    if (cue && cue.sceneId !== line.sceneId) line.cueId = null;
    commit();
    selectedId = line.id;
    render();
  }

  /* ---------- 本体・タイムラインとのつなぎ ---------- */

  // 劇場設定・セリフキューパネルと同じく、言語パック適用後の <html lang> を購読する。
  new MutationObserver(() => {
    syncChromeLanguage();
    if (!isOpen) return; // 再訪時の render() で中身も新しい言語にそろえる
    if (inlineEdit) {
      // 入力中の本文を作り直さず、残りの表示だけを更新する。
      inlineEdit.input.setAttribute("aria-label", tx("セリフ"));
      renderSummary(); renderToc(); renderInspector();
    } else render();
  }).observe(document.documentElement, { attributes: true, attributeFilter: ["lang"] });

  // タイムラインが出すセリフキューの一覧（全セクション）。キューの番号・シーン・秒はここから読む
  window.addEventListener("stage-timeline-vox-cues", (event) => {
    const detail = event && event.detail || {};
    voxCues = [];
    (Array.isArray(detail.sections) ? detail.sections : []).forEach((section) => {
      (Array.isArray(section.cues) ? section.cues : []).forEach((cue) => voxCues.push({
        id: cue.id, displayName: cue.displayName, sceneId: cue.sceneId, seconds: cue.seconds, sectionTitle: section.sectionTitle,
      }));
    });
    if (!isOpen) return;
    if (inlineEdit) return;      // その場で直している最中は描き直さない（確定したときに描き直す）
    if (selfCommit || commitTimer) {
      // 自分の書き込みの結果: 入力中の欄は作り直さず、一覧と数だけ更新する
      try { project = JSON.parse(bridge.exportDocumentString()).project; } catch (_) { /* そのまま */ }
      renderSummary(); renderToc(); renderLines();
      return;
    }
    // 取り消し・やり直し・別のショーを開いた等: 本体から読み直して全部描き直す
    readProject();
    render();
  });

  window.SHOSAI_SCRIPT_EDITOR = Object.freeze({
    open() {
      isOpen = true;
      readProject();
      if (!ui.body) build();
      window.dispatchEvent(new CustomEvent("stage-vox-panel-request"));
      render();
    },
    close() {
      flushTextTimer();
      isOpen = false;
    },
  });
}());
